function GlassKilnSootScraperMaker.init() GlassKilnSootScraperMaker.ironStock=14; GlassKilnSootScraperMaker.bronzeStock=12; GlassKilnSootScraperMaker.woodStock=14; GlassKilnSootScraperMaker.leatherStock=8; GlassKilnSootScraperMaker.silverStock=8; GlassKilnSootScraperMaker.goldStock=6; GlassKilnSootScraperMaker.jewelStock=4; GlassKilnSootScraperMaker.pearlStock=4; GlassKilnSootScraperMaker.productStock={}; GlassKilnSootScraperMaker.buildings={}; GlassKilnSootScraperMaker.maker=nil; GlassKilnSootScraperMaker.activeMaking={}; GlassKilnSootScraperMaker.totalProducts=0; GlassKilnSootScraperMaker.dayTimer=0; print("[GlassKilnSootScraperMaker] Royal Glass Kiln Soot Scraper Maker System initialized (6 products, 4 buildings)") end
function GlassKilnSootScraperMaker.hireMaker(n,s) s=s or math.random(55,90); local c=575+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; GlassKilnSootScraperMaker.maker={name=n or ("Strgar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Strgar najet: %s (spretnost: %d)",GlassKilnSootScraperMaker.maker.name,s),"success") end; return true end
function GlassKilnSootScraperMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function GlassKilnSootScraperMaker.build(id) local ok,e=GlassKilnSootScraperMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(GlassKilnSootScraperMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function GlassKilnSootScraperMaker.getQualityBonus() local b=0; for _,bd in ipairs(GlassKilnSootScraperMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function GlassKilnSootScraperMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and GlassKilnSootScraperMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and GlassKilnSootScraperMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and GlassKilnSootScraperMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and GlassKilnSootScraperMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and GlassKilnSootScraperMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and GlassKilnSootScraperMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and GlassKilnSootScraperMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and GlassKilnSootScraperMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #GlassKilnSootScraperMaker.buildings==0 then return false,"Potrebna strgalna delavnica" end; if not GlassKilnSootScraperMaker.maker then return false,"Potreben strgar" end; return true end
function GlassKilnSootScraperMaker.make(pt,qty) qty=qty or 1; local ok,e=GlassKilnSootScraperMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then GlassKilnSootScraperMaker.ironStock=GlassKilnSootScraperMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then GlassKilnSootScraperMaker.bronzeStock=GlassKilnSootScraperMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then GlassKilnSootScraperMaker.woodStock=GlassKilnSootScraperMaker.woodStock-d.woodCost*qty end; if d.leatherCost then GlassKilnSootScraperMaker.leatherStock=GlassKilnSootScraperMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then GlassKilnSootScraperMaker.silverStock=GlassKilnSootScraperMaker.silverStock-d.silverCost*qty end; if d.goldCost then GlassKilnSootScraperMaker.goldStock=GlassKilnSootScraperMaker.goldStock-d.goldCost*qty end; if d.jewelCost then GlassKilnSootScraperMaker.jewelStock=GlassKilnSootScraperMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then GlassKilnSootScraperMaker.pearlStock=GlassKilnSootScraperMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if GlassKilnSootScraperMaker.maker then t=math.max(1,t-math.floor(GlassKilnSootScraperMaker.maker.skill/13)) end; table.insert(GlassKilnSootScraperMaker.activeMaking,{id="glasskilnsootscraper_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function GlassKilnSootScraperMaker.completeMaking(m) local q=1.0+(GlassKilnSootScraperMaker.getQualityBonus()/100); if GlassKilnSootScraperMaker.maker then q=q+(GlassKilnSootScraperMaker.maker.skill/140) end; q=math.min(2.5,q); GlassKilnSootScraperMaker.productStock[m.productType]=(GlassKilnSootScraperMaker.productStock[m.productType] or 0)+m.quantity; GlassKilnSootScraperMaker.totalProducts=GlassKilnSootScraperMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if GlassKilnSootScraperMaker.maker then GlassKilnSootScraperMaker.maker.itemsMade=GlassKilnSootScraperMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then GlassKilnSootScraperMaker.maker.skill=math.min(100,GlassKilnSootScraperMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Strgalo izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"glasskilnsootscraper.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function GlassKilnSootScraperMaker.update(dt) if not _G.state then return end; GlassKilnSootScraperMaker.dayTimer=GlassKilnSootScraperMaker.dayTimer+dt; if GlassKilnSootScraperMaker.dayTimer>=30 then GlassKilnSootScraperMaker.dayTimer=0; for i=#GlassKilnSootScraperMaker.activeMaking,1,-1 do local m=GlassKilnSootScraperMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then GlassKilnSootScraperMaker.completeMaking(m); table.remove(GlassKilnSootScraperMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(GlassKilnSootScraperMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if GlassKilnSootScraperMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
